package com.fitnutri.backend.records.food;
import com.fitnutri.backend.common.*;
import com.fitnutri.backend.foodreference.*;
import com.fitnutri.backend.profile.ProfileService;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.submission.SubmissionService;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
import static com.fitnutri.backend.records.food.FoodEntryInputs.*;

/** Owner → root → sorted references → sorted leaves. Explicit SQL increments the parent once even with a fixed clock. */
@Service
public class FoodEntryMutationService {
 private final RecordMutationGuard guard;private final JdbcTemplate jdbc;private final FoodSnapshotReader snapshots;private final FoodEntryPreviewService previews;private final FoodReferenceRepository references;private final SubmissionService submissions;private final ProfileService profiles;private final PortionNormalizer portions;private final ObjectMapper json;private final CanonicalV2Json canonical;private final Clock clock;
 public FoodEntryMutationService(RecordMutationGuard guard,JdbcTemplate jdbc,FoodSnapshotReader snapshots,FoodEntryPreviewService previews,FoodReferenceRepository references,SubmissionService submissions,ProfileService profiles,PortionNormalizer portions,ObjectMapper json,CanonicalV2Json canonical,Clock clock){this.guard=guard;this.jdbc=jdbc;this.snapshots=snapshots;this.previews=previews;this.references=references;this.submissions=submissions;this.profiles=profiles;this.portions=portions;this.json=json;this.canonical=canonical;this.clock=clock;}
 @Transactional public FoodSnapshotReader.Root updateOwnedRoot(Long owner,String kind,long id,UpdateRequest request){
  guard.lockOwner(owner);if(request==null)throw BusinessException.invalid("request","Review a complete food correction.");guard.versionInput(request.expectedVersion());var row=lock(owner,kind,id);if(row.get("deleted_at")!=null)throw missing();version(row,request.expectedVersion());var old=snapshots.detailForReuse(owner,kind,id);if(request.entry()==null)throw BusinessException.invalid("entry","Review a complete food entry.");previews.validateInputs(new PreviewRequest(request.recordDate(),request.zone(),RecordSource.valueOf(old.source()),List.of(request.entry())));
  var selected=new TreeSet<Long>();collect(request.entry(),selected);collect(json.convertValue(old.input(),Entry.class),selected);Map<Long,FoodReference> loaded=new HashMap<>();for(var reference:references.lockAllById(selected))loaded.put(reference.getId(),reference);
  var oldRows=kind.equals("single")?List.of(row):jdbc.queryForList("SELECT * FROM food_record WHERE user_id=? AND dish_id=? ORDER BY id FOR UPDATE",owner,id);
  Map<UUID,Map<String,Object>> active=new HashMap<>();for(var leaf:oldRows)if(leaf.get("deleted_at")==null)active.put((UUID)leaf.get("client_entry_id"),leaf);
  var incoming=leafIds(request.entry());submissions.requireUnusedEntryIdentities(owner,incoming.stream().filter(uuid->!active.containsKey(uuid)).toList());
  var preview=previews.previewOwnedRoot(owner,kind,id,new CorrectionRequest(request.expectedVersion(),request.recordDate(),request.zone(),request.entry()));
  if(old.recordDate().equals(request.recordDate())&&canonical.canonical(normalise(json.convertValue(old.input(),Entry.class))).equals(canonical.canonical(normalise(request.entry()))))return old;
  profiles.requireCompletedAdultSetup(owner);var originalPreview=previews.previewOwnedRoot(owner,kind,id,new CorrectionRequest(request.expectedVersion(),old.recordDate(),request.zone(),json.convertValue(old.input(),Entry.class)));
  if(!preview.fingerprint().equals(originalPreview.fingerprint())){if(request.previewFingerprint()==null||!request.previewFingerprint().matches("[0-9a-f]{64}"))throw BusinessException.invalid("previewFingerprint","Review the changed food calculation before confirming.");if(!request.previewFingerprint().equals(preview.fingerprint()))throw new FoodCalculationChangedV2Exception(preview);}
  var calculated=new HashMap<UUID,FoodSnapshotReader.Leaf>();for(var leaf:preview.entries().getFirst().leaves())calculated.put(leaf.clientEntryId(),leaf);var now=clock.instant();
  if(request.entry() instanceof Single single){var values=values(row,single.referenceId(),single.mealType(),single.selectionKind(),single.searchMetadataRevision(),null,calculated.get(single.clientEntryId()),loaded,request.recordDate());updateLeaf(owner,row,values,now);}
  else{var dish=(Dish)request.entry();var ratio=portions.normalisePortion(dish.inputMode(),dish.portion());int changed=jdbc.update("UPDATE food_dish_record SET name=?,meal_type=?,recorded_date=?,input_mode=?,portion_input_kind=?,portion_numerator=?,portion_denominator=?,portion_input_json=?::jsonb,updated_at=?,version=version+1 WHERE user_id=? AND id=? AND version=?",dish.name(),dish.mealType().name(),request.recordDate(),dish.inputMode(),ratio.kind(),ratio.numerator(),ratio.denominator(),json.writeValueAsString(ratio.input()),java.sql.Timestamp.from(now),owner,id,request.expectedVersion());if(changed!=1)throw conflict();
   for(var leaf:active.entrySet())if(!incoming.contains(leaf.getKey()))jdbc.update("UPDATE food_record SET deleted_at=?,updated_at=?,version=version+1 WHERE user_id=? AND id=?",java.sql.Timestamp.from(now),java.sql.Timestamp.from(now),owner,leaf.getValue().get("id"));
   for(int position=0;position<dish.ingredients().size();position++){var ingredient=dish.ingredients().get(position);var prior=active.get(ingredient.clientEntryId());var values=values(prior,ingredient.referenceId(),dish.mealType(),ingredient.selectionKind(),ingredient.searchMetadataRevision(),position,calculated.get(ingredient.clientEntryId()),loaded,request.recordDate());if(prior!=null)updateLeaf(owner,prior,values,now);else{values.put("user_id",owner);values.put("dish_id",id);values.put("client_entry_id",ingredient.clientEntryId());values.put("source",row.get("source"));values.put("created_at",java.sql.Timestamp.from(now));values.put("updated_at",java.sql.Timestamp.from(now));values.put("recorded_at",java.sql.Timestamp.from(now));jdbc.update("INSERT INTO food_record("+String.join(",",values.keySet())+") VALUES("+String.join(",",Collections.nCopies(values.size(),"?"))+")",values.values().toArray());}}
  }
  return snapshots.detailForReuse(owner,kind,id);
 }
 @Transactional public void softDeleteOwnedRoot(Long owner,String kind,long id,Long expectedVersion){guard.versionInput(expectedVersion);guard.lockOwner(owner);var root=lock(owner,kind,id);if(root.get("deleted_at")!=null)return;version(root,expectedVersion);var now=java.sql.Timestamp.from(clock.instant());if(kind.equals("dish"))jdbc.update("UPDATE food_record SET deleted_at=?,updated_at=?,version=version+1 WHERE user_id=? AND dish_id=? AND deleted_at IS NULL",now,now,owner,id);jdbc.update("UPDATE "+table(kind)+" SET deleted_at=?,updated_at=?,version=version+1 WHERE user_id=? AND id=? AND version=?",now,now,owner,id,expectedVersion);}
 private Map<String,Object> lock(Long owner,String kind,long id){guard.id(id);String table=table(kind);var rows=jdbc.queryForList("SELECT * FROM "+table+" WHERE user_id=? AND id=?"+(kind.equals("single")?" AND dish_id IS NULL":"")+" FOR UPDATE",owner,id);if(rows.isEmpty())throw missing();return rows.getFirst();}
 private static String table(String kind){if("single".equals(kind))return "food_record";if("dish".equals(kind))return "food_dish_record";throw BusinessException.invalid("kind","Choose a single food or dish.");}
 private static void version(Map<String,Object> row,Long expected){if(((Number)row.get("version")).longValue()!=expected)throw conflict();}
 private static BusinessException conflict(){return new BusinessException(HttpStatus.CONFLICT,"VERSION_CONFLICT","Reload and review the current food entry.");}
 private static BusinessException missing(){return new BusinessException(HttpStatus.NOT_FOUND,"NOT_FOUND","Food record not found.");}
 private static void collect(Entry entry,Set<Long> ids){if(entry instanceof Single s)ids.add(FoodEntryInputValidator.referenceId(s.referenceId()));else if(entry instanceof Dish d&&d.ingredients()!=null)for(var ingredient:d.ingredients())if(ingredient!=null)ids.add(FoodEntryInputValidator.referenceId(ingredient.referenceId()));}
 private static List<UUID> leafIds(Entry entry){if(entry instanceof Single s)return List.of(s.clientEntryId());if(entry instanceof Dish d&&d.ingredients()!=null)return d.ingredients().stream().map(Ingredient::clientEntryId).toList();throw BusinessException.invalid("entry","Review a complete food entry.");}
 private static Entry normalise(Entry entry){if(entry instanceof Single s)return new Single(s.clientEntryId(),s.referenceId(),s.quantityGrams(),s.mealType(),s.selectionKind()==null?"USER_SELECTED":s.selectionKind(),s.searchMetadataRevision());var d=(Dish)entry;return new Dish(d.clientEntryId(),d.name(),d.mealType(),d.inputMode(),d.portion(),d.ingredients().stream().map(i->new Ingredient(i.clientEntryId(),i.referenceId(),i.inputGrams(),i.selectionKind()==null?"USER_SELECTED":i.selectionKind(),i.searchMetadataRevision())).toList(),d.originDishId());}
 private static LinkedHashMap<String,Object> values(Map<String,Object> prior,String referenceId,MealType meal,String selection,String metadata,Integer position,FoodSnapshotReader.Leaf calculated,Map<Long,FoodReference> references,LocalDate date){var reference=references.get(FoodEntryInputValidator.referenceId(referenceId));if(reference==null||calculated==null)throw new IllegalStateException("Validated food leaf is missing.");var values=new LinkedHashMap<String,Object>();values.put("food_reference_id",reference.getId());values.put("food_name",prior!=null&&reference.getId().equals(prior.get("food_reference_id"))?prior.get("food_name"):reference.getDisplayName());values.put("quantity_grams",calculated.consumedGrams());values.put("meal_type",meal.name());values.put("recorded_date",java.sql.Date.valueOf(date));values.put("energy_kj",calculated.nutrients().energyKj());values.put("protein_grams",calculated.nutrients().proteinGrams());values.put("fat_grams",calculated.nutrients().fatGrams());values.put("carbs_grams",calculated.nutrients().carbsGrams());values.put("selection_kind",selection==null?"USER_SELECTED":selection);values.put("search_metadata_revision",metadata);values.put("dish_position",position);values.put("ingredient_input_grams",position==null?null:calculated.inputGrams());values.put("nutrition_policy",position==null?"REFERENCE_GRAMS_V1":DishCalculationService.POLICY);boolean retained=prior!=null&&same(prior.get("food_reference_id"),reference.getId())&&same(prior.get("quantity_grams"),calculated.consumedGrams())&&same(prior.get("energy_kj"),calculated.nutrients().energyKj())&&same(prior.get("protein_grams"),calculated.nutrients().proteinGrams())&&same(prior.get("fat_grams"),calculated.nutrients().fatGrams())&&same(prior.get("carbs_grams"),calculated.nutrients().carbsGrams());values.put("data_quality",retained?prior.get("data_quality"):DataQuality.CURRENT.name());return values;}
 private void updateLeaf(Long owner,Map<String,Object> prior,LinkedHashMap<String,Object> values,Instant now){boolean dirty=values.entrySet().stream().anyMatch(e->!same(prior.get(e.getKey()),e.getValue()));if(!dirty)return;var args=new ArrayList<Object>(values.values());args.add(java.sql.Timestamp.from(now));args.add(owner);args.add(prior.get("id"));jdbc.update("UPDATE food_record SET "+String.join(",",values.keySet().stream().map(k->k+"=?").toList())+",updated_at=?,version=version+1 WHERE user_id=? AND id=?",args.toArray());}
 private static boolean same(Object a,Object b){if(a instanceof BigDecimal x&&b instanceof BigDecimal y)return x.compareTo(y)==0;return Objects.equals(a,b);}
}
